const input = $input.first().json;

const featureName = input.body?.feature_name || 'Unknown Feature';
const featureDescription = input.body?.description || '';
const testCases = input.body?.test_cases || [];
const author = input.body?.author || 'N/A';
const priority = input.body?.priority || 'Medium';
const category = input.body?.category || 'Functional';

const now = new Date();
const dateStr = now.toISOString().split('T')[0];

let testCaseRows = '';
if (testCases.length > 0) {
  testCaseRows = testCases.map((tc, i) => {
    const id = String(i + 1).padStart(3, '0');
    return `| TC-${id} | ${tc.name || ''} | ${tc.precondition || '-'} | ${tc.steps || ''} | ${tc.expected || ''} | ${tc.priority || priority} | - |`;
  }).join('\n');
} else {
  testCaseRows = '| TC-001 | (テストケースを追加してください) | - | - | - | Medium | - |';
}

const markdown = `# テスト仕様書: ${featureName}

## 基本情報

| 項目 | 内容 |
|------|------|
| 機能名 | ${featureName} |
| 作成日 | ${dateStr} |
| 作成者 | ${author} |
| カテゴリ | ${category} |
| 優先度 | ${priority} |

## 機能概要

${featureDescription}

## テスト環境

| 項目 | 内容 |
|------|------|
| OS | - |
| ブラウザ | - |
| テストサーバー | - |
| テストデータ | - |

## 前提条件

- (前提条件を記載)

## テストケース

| ID | テスト名 | 前提条件 | 手順 | 期待結果 | 優先度 | 結果 |
|----|----------|----------|------|----------|--------|------|
${testCaseRows}

## テスト結果サマリ

| 項目 | 件数 |
|------|------|
| 総テストケース数 | ${testCases.length || 0} |
| 成功 | - |
| 失敗 | - |
| 未実施 | ${testCases.length || 0} |

## 備考

- 
`;

return [{ json: { markdown, feature_name: featureName, date: dateStr } }];
